static const char *const search_web_script[] = {
"'use strict';\n"
"function element(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;"
"if(className)node.className=className;return node;}\n"
"async function api(path,signal){const response=await fetch(path,{signal,headers:{Accept:'application/json'}});"
"const data=await response.json();if(!response.ok)throw new Error(data.error||('HTTP '+response.status));return data;}\n"
"const count=new Intl.NumberFormat('de-DE');\n"
"function bytes(value){return count.format(value/1048576)+' MiB ('+count.format(value)+' Bytes)';}\n"
"function date(value){const match=/^(\\d{4})-(\\d{2})-(\\d{2})/.exec(value||'');"
"return match?match[3]+'.'+match[2]+'.'+match[1]:value;}\n"
"function original(parent,id,label){if(!/^https?:\\/\\//i.test(id||''))return;"
"const link=element('a',label);link.href=id;link.target='_blank';link.rel='noopener noreferrer';parent.append(link);return link;}\n"
"function originalPdf(parent,url,label,version,page){const link=original(parent,url,label);"
"if(link&&/^[a-f0-9]{64}$/.test(version?.sha256||'')){link.dataset.pdfHash=version.sha256;"
"link.dataset.pdfPage=String(page||1);link.dataset.pdfBytes=String(version.bytes);}return link;}\n"
"function localLink(parent,path,label){const link=element('a',label);link.href=path;parent.append(link);return link;}\n"
"function paperUrl(id){return '/paper?'+new URLSearchParams({id});}\n"
"function documentUrl(metadata){return [metadata.downloadUrl,metadata.accessUrl].find(value=>"
"typeof value==='string'&&/^https?:\\/\\//i.test(value))||'';}\n"
"function contextDate(value){return value.precision==='invalid'?'Ung\\u00fcltiges Datum: '+value.value:date(value.value);}\n"
"function genericDocumentTitle(name){return /^(Sammeldokument|Protokoll|Alle Anlagen) (\\u00f6ffentlich|oeffentlich)$/i.test((name||'').trim());}\n"
"function hitTitle(hit){const name=hit.relatedName||hit.name;if(name&&!genericDocumentTitle(name))return name;"
"if(genericDocumentTitle(name)){const pdf=hit.preparation?.context;if(pdf?.kind==='protocol-top'&&pdf.heading?.text)return pdf.heading.text;const sources=new Map();"
"for(const edge of hit.evidence?.relationshipPath||[])if(['Paper','AgendaItem','Meeting'].includes(edge.sourceKind)&&"
"edge.sourceName&&!genericDocumentTitle(edge.sourceName))sources.set(edge.source,edge);"
"if(sources.size===1&&hit.evidence?.relationshipsComplete!==false&&"
"!(hit.evidence?.relationshipPath||[]).some(edge=>edge.sourceNameOmitted)){"
"const context=[...sources.values()][0];if(context.sourceKind!=='Meeting')return context.sourceName;"
"const label=/^Protokoll /i.test(name)?'Protokoll':/^Alle Anlagen /i.test(name)?'Anlagen':'Sitzungsdokument';return label+': '+context.sourceName;}"
"return hit.fileName||hit.relatedReference||hit.reference||'Dokument ohne aussagekr\\u00e4ftigen Titel';}"
"return hit.relatedReference||hit.reference||hit.fileName||hit.id;}\n",
"const pdfLabels={'document.date':'Dokumentdatum','document.releaseDate':'Freigabe','document.reference':'Kennzeichen',"
"'originator.label':'Einreicher laut PDF','department.label':'Gesch\\u00e4ftsbereich','document.role':'Dokumentrolle',"
"'submission.receivedDate':'Anfrageeingang','submission.forwardedDate':'Weiterleitung','answer.dueDate':'Antwortfrist',"
"'answer.extendedDueDate':'Verl\\u00e4ngerte Frist','answer.receivedDate':'Beantwortungseingang'};"
"const pdfColumns={date:'Sitzungstermin laut PDF',committee:'Gremium',responsibility:'Zust\\u00e4ndigkeit',number:'TOP',text:'Text / Einreicher',reference:'Drucksache'};"
"const pdfRoles={answer:'Antwort', 'deadline-extension':'Fristverl\\u00e4ngerung'};\n"
"function pdfFacts(preparation){if(!preparation)return null;const fields=preparation.fields||[],counts=preparation.structure||{};"
"if(!fields.some(f=>f.status==='rule-supported')&&!counts.agendaItems&&!counts.tables&&!preparation.fieldIssues&&"
"!['pdf-warnings','unsupported-layout','ambiguous'].includes(preparation.pageStatus)&&preparation.status==='complete')return null;"
"const box=element('aside',undefined,'pdf-facts');"
"box.append(element('h3','Aus dem PDF'));const facts=element('dl',undefined,'fact-grid');"
"for(const field of preparation.fields||[]){if(field.status!=='rule-supported')continue;"
"const value=field.field==='document.role'?(pdfRoles[field.value]||field.value):field.field.endsWith('Date')||field.field==='document.date'?date(field.value):field.value;"
"facts.append(element('dt',pdfLabels[field.field]||field.field),element('dd',value));}"
"if(facts.children.length)box.append(facts);const parts=[];"
"if(counts.agendaItems)parts.push(count.format(counts.agendaItems)+(counts.agendaItems===1?' TOP-Befund':' TOP-Befunde'));"
"if(counts.tables)parts.push(count.format(counts.tables)+(counts.tables===1?' Tabelle':' Tabellen'));"
"if(parts.length)box.append(element('p',parts.join(' \\u00b7 '),'pdf-note'));"
"if(counts.uncertainRows)box.append(element('p',count.format(counts.uncertainRows)+(counts.uncertainRows===1?' unsicher zugeordnete Tabellenzeile':' unsicher zugeordnete Tabellenzeilen'),'uncertain'));"
"if(preparation.fieldIssues)box.append(element('p',preparation.fieldIssues+(preparation.fieldIssues===1?' Formularfeld nicht sicher erschlossen':' Formularfelder nicht sicher erschlossen'),'pdf-note'));"
"if(preparation.status==='failed')box.append(element('p','PDF-Textextraktion fehlgeschlagen.','uncertain'));"
"if(preparation.status==='warnings')box.append(element('p','Das Dokument enth\\u00e4lt Extraktionswarnungen.','pdf-note'));"
"if(preparation.pageStatus&&['pdf-warnings','unsupported-layout','ambiguous'].includes(preparation.pageStatus))"
"box.append(element('p',preparation.pageStatus==='ambiguous'?'Seitenstruktur teilweise unklar':'Seitenstruktur wegen Extraktions-/Layoutl\\u00fccken nicht sicher erschlossen','uncertain'));"
"box.append(element('p','Automatisch aus PDF-Textpositionen erschlossen.','pdf-note'));return box;}\n",
"function pdfContext(preparation,title){const context=preparation?.context;if(!context)return null;"
"const box=element('section',undefined,'pdf-context');"
"const matching=preparation.selection==='matching-text';"
"if(context.kind==='protocol-top'){box.append(element('h3',(matching?'Passender TOP ':'TOP auf dieser Seite ')+context.number+' \\u00b7 Protokollauszug'));"
"if(context.heading?.text&&context.heading.text!==title)box.append(element('p',context.heading.text));"
"if(context.outcome?.text)box.append(element('p','Ergebnis laut PDF: '+context.outcome.text));"
"if(context.references?.length)box.append(element('p',context.references.map(r=>r.text).join(' \\u00b7 '),'muted'));"
"}else{box.append(element('h3',context.kind==='agenda'?'Passende Tagesordnungszeile (PDF)':'Passende Beratungszeile (PDF)'));"
"const row=element('dl',undefined,'fact-grid');for(const [i,column] of context.columns.entries())"
"row.append(element('dt',pdfColumns[column]||column),element('dd',context.cells[i]?.text||'Nicht angegeben'));box.append(row);}"
"if(context.status==='ambiguous')box.append(element('p','Zeilenzuordnung unsicher; keine fehlenden Werte erg\\u00e4nzt.','uncertain'));return box;}\n"
"function cellProof(parent,cell,raw){if(!cell?.sources?.length||!raw)return;"
"const detail=element('details',undefined,'cell-proof');detail.append(element('summary','Textbeleg'));let loaded=false;"
"detail.addEventListener('toggle',()=>{if(!detail.open||loaded)return;loaded=true;"
"const decoder=new TextDecoder();detail.append(element('pre',cell.sources.map(s=>"
"decoder.decode(raw.subarray(s.start,s.start+s.length))).join('\\n')));});parent.append(detail);}\n",
"function renderPdfFields(parent,preparation){if(!preparation?.fields?.length)return;"
"const detail=element('details');detail.append(element('summary','Formularfelder und Fundstellen ('+preparation.fields.length+')'));"
"const statuses={missing:'Nicht ausgef\\u00fcllt',ambiguous:'Mehrdeutig',invalid:'Ung\\u00fcltig',placeholder:'Platzhalter',"
"'too-long':'Wert zu lang','unsupported-placement':'Position nicht sicher zugeordnet'};"
"for(const field of preparation.fields){const block=element('section',undefined,'pdf-top');"
"block.append(element('h4',pdfLabels[field.field]||field.field));"
"block.append(element('p',field.status==='rule-supported'?(field.field==='document.role'?(pdfRoles[field.value]||field.value):field.value):"
"(statuses[field.status]||field.status),field.status==='rule-supported'?'':'uncertain'));"
"block.append(element('p','PDF-Seite '+field.page+(field.sourceLabel?' \\u00b7 '+field.sourceLabel:''),'pdf-note'));"
"if(field.sourceText)block.append(element('pre',field.sourceText));detail.append(block);}parent.append(detail);}\n",
"function renderPdfPage(parent,preparation){const page=preparation?.pageData;if(!page){"
"renderPdfFields(parent,preparation);if(preparation?.status==='failed')parent.append(element('p','PDF-Textextraktion fehlgeschlagen: '+preparation.error,'warning'));"
"else if(preparation)parent.append(element('p','Dieser Index enth\\u00e4lt noch keine seitenbezogenen PDF-Strukturen. Neuaufbau mit --prepared erforderlich.','pdf-note'));return;}"
"renderPdfFields(parent,preparation);"
"const structure=page.structure,raw=page.layout?new TextEncoder().encode(page.layout.text):null;"
"const issues={unrecognized:'Keines der bekannten Tabellen-/TOP-Muster erkannt.',ambiguous:'Einige Strukturzuordnungen sind unklar.',"
"'pdf-warnings':'Extraktionswarnungen: keine sichere Seitenstruktur.', 'unsupported-layout':'Die Textgeometrie erlaubt keine sichere Strukturierung.'};"
"if(issues[structure.status])parent.append(element('p',issues[structure.status],'pdf-note'));"
"for(const item of structure.agendaItems||[]){if(item.kind!=='protocol-top')continue;"
"const block=element('section',undefined,'pdf-top');block.append(element('h4',item.heading.text||'TOP '+item.number));cellProof(block,item.heading,raw);"
"if(item.references.length)block.append(element('p',item.references.map(r=>r.text).join(' \\u00b7 '),'muted'));"
"if(item.outcome){block.append(element('p','Ergebnis laut PDF: '+item.outcome.text));cellProof(block,item.outcome,raw);}"
"if(item.body.text){block.append(element('p',item.body.text));cellProof(block,item.body,raw);}parent.append(block);}"
"for(const [index,table] of (structure.tables||[]).entries()){const scroll=element('div',undefined,'pdf-tables'),node=element('table');"
"node.append(element('caption',(table.kind==='agenda'?'Tagesordnung':'Beratungsfolge')+' \\u00b7 PDF-Seite '+page.page));"
"const head=element('thead'),headers=element('tr');for(const column of table.columns){const th=element('th',pdfColumns[column]||column);th.scope='col';headers.append(th);}head.append(headers);node.append(head);"
"const body=element('tbody'),sections=new Map((structure.agendaItems||[]).filter(i=>i.kind==='agenda-top'&&i.table===index).map(i=>[i.row,i.section]));"
"for(const [position,row] of table.rows.entries()){const tr=element('tr');tr.dataset.uncertain=String(row.status==='ambiguous');"
"for(const [i,cell] of row.cells.entries()){const td=element('td',cell.text||'Nicht angegeben');"
"if(i===0&&sections.get(position)&&sections.get(position)!=='unknown')td.append(element('p',sections.get(position)==='public'?'\\u00d6ffentlicher Teil':'Nicht\\u00f6ffentlicher Teil (ver\\u00f6ffentlichte Datei)','pdf-note'));"
"if(i===0&&row.status==='ambiguous')td.append(element('p','Zuordnung unsicher','uncertain'));"
"cellProof(td,cell,raw);tr.append(td);}body.append(tr);}node.append(body);scroll.append(node);parent.append(scroll);}"
"if(structure.diagnostics?.length){const detail=element('details');detail.append(element('summary','Regelgrenzen und Diagnosen'),"
"element('pre',structure.diagnostics.join('\\n')));parent.append(detail);}}\n",
"async function loadPdfPage(parent,parameters){const data=await api('/api/object?'+new URLSearchParams(parameters));parent.replaceChildren();"
"renderPdfPage(parent,data.preparation);const page=data.page||Number(parameters.page)||1,total=data.preparation?.pageCount||0;"
"if(total>1){const nav=element('nav',undefined,'page-navigation');nav.ariaLabel='PDF-Seiten';"
"for(const [step,label] of [[-1,'Vorherige PDF-Seite'],[1,'N\\u00e4chste PDF-Seite']]){const button=element('button',label);button.type='button';button.disabled=page+step<1||page+step>total;"
"button.addEventListener('click',async()=>{button.disabled=true;try{await loadPdfPage(parent,{...parameters,page:page+step});}"
"catch(error){parent.replaceChildren(element('p','Fehler: '+error.message,'warning'));}});nav.append(button);"
"if(step===-1)nav.append(element('span','PDF-Seite '+page+' von '+total));}parent.append(nav);}"
"if(data.text){const text=element('details');text.append(element('summary','Vollst\\u00e4ndiger Seitentext'),element('pre',data.text));parent.append(text);}"
"const metadata=element('details');metadata.append(element('summary','RIS-Rohmetadaten'),element('pre',JSON.stringify(data.metadata,null,2)));parent.append(metadata);"
"localLink(parent,'/api/object?'+new URLSearchParams({...parameters,raw:'true'}),'Vollst\\u00e4ndige Daten mit PDF-Textpositionen (JSON)');}\n",
"async function health(){const status=document.querySelector('#health-status');try{const data=await api('/api/status');"
"status.textContent=data.incomplete?'Bekannte Archiv- oder Texterkennungsl\\u00fccken':'Keine bekannten Indexl\\u00fccken';"
"if(data.incomplete)status.className='warning';"
"const stats=document.querySelector('#health-stats');"
"for(const [label,value] of [['Indexgr\\u00f6\\u00dfe',bytes(data.indexBytes)],['Indexspeicher',bytes(data.indexMemoryBytes)],"
"['Datens\\u00e4tze',count.format(data.records)],['Suchbegriffe',count.format(data.terms)],['PDF-Seiten',count.format(data.pages)],"
"['Seiten mit Extraktionswarnung',count.format(data.warningPages)],['Seiten mit OCR-Bedarf',count.format(data.ocrPages)]]){"
"const item=element('div',undefined,'panel');item.append(element('dt',label),element('dd',value));stats.append(item);}"
"for(const [label,value] of [['Snapshot',data.snapshotId],['Lokaler Indeximport',new Date(data.importedAtEpochSeconds*1000).toISOString()]]){"
"const item=element('div',undefined,'panel');item.append(element('dt',label),element('dd',value));stats.append(item);}"
"for(const type of data.coverage?.perType||[]){const item=element('div',undefined,'panel');item.append(element('dt',type.kind),"
"element('dd',count.format(type.records)+' Datens\\u00e4tze; '+count.format(type.localWarningRecords)+' lokale Warnungen; '+"
"count.format(type.unresolvedRelationTargets)+' fehlende Beziehungsziele; '+count.format(type.filesWithoutIndexedVersion)+' Files ohne Dokumentfassung'));"
"if(type.filesWithoutIndexedVersion)item.append(element('p',"
"count.format(type.fileVersionReasons.notArchivedAtIndexBuild)+' beim Indexaufbau nicht lokal archiviert; '+"
"count.format(type.fileVersionReasons.unknown)+' ohne belegbare Ursache. Daraus folgen keine bestimmten Downloadfehler.','muted'));"
"if(type.unresolvedReasons?.explicitlyNonpublic)item.append(element('p',"
"count.format(type.unresolvedReasons.explicitlyNonpublic)+' Beziehungsziele ausdr\\u00fccklich nicht\\u00f6ffentlich.','muted'));stats.append(item);}"
"document.querySelector('#health-coverage').textContent=data.incomplete?"
"'Der Index ist unvollst\\u00e4ndig: Archiv- oder Texterkennungsl\\u00fccken sind bekannt. Details stehen im Abdeckungsbericht des Indexers.':"
"'Beim Indexaufbau wurden keine Archiv- oder Extraktionsl\\u00fccken festgestellt. Das ist keine Garantie f\\u00fcr die Vollst\\u00e4ndigkeit des RIS.';"
"}catch(error){status.textContent='Fehler: '+error.message;status.className='warning';}}\n",
"function initSearch(){const form=document.querySelector('#search'), results=document.querySelector('#results');"
"const status=document.querySelector('#status'), sortHelp=document.querySelector('#sort-help');"
"const ordering=document.querySelector('#ordering'), direction=document.querySelector('#chronology-direction'), method=document.querySelector('#search-method');"
"const navs=[...document.querySelectorAll('.pagination')];"
"let controller, sequence=0, active, total=0, chronologicalSort='date-desc';\n"
"const filterNames=['year','paperType','organization','organizationId','actorId','kind','dateFrom','dateThrough'];"
"function hasCriteria(params){return !!(params.get('q')||'').trim()||filterNames.some(name=>params.get(name))||params.get('group')==='document';}"
"function syncOrdering(){const sort=form.elements.namedItem('sort').value, mode=form.elements.namedItem('mode').value;"
"const chronological=sort==='date-asc'||sort==='date-desc';if(chronological)chronologicalSort=sort;"
"ordering.value=chronological?'chronological':mode;direction.hidden=method.hidden=!chronological;"
"const ascending=sort==='date-asc';direction.textContent=ascending?'\\u2191':'\\u2193';"
"direction.setAttribute('aria-label',(ascending?'\\u00c4lteste zuerst. Neueste':'Neueste zuerst. \\u00c4lteste')+' zuerst anzeigen.');"
"direction.title=direction.getAttribute('aria-label');"
"method.textContent='Suchart: '+({lexical:'Wortsuche',semantic:'Thematisch',hybrid:'Kombiniert'}[mode]||mode);}\n"
"function restore(params){for(const name of ['q',...filterNames,'dateRole','group','limit','sort','mode']){"
"form.elements.namedItem(name).value=params.get(name)||(name==='limit'?'50':name==='sort'?'relevance':name==='mode'?'lexical':name==='group'?'paper':name==='dateRole'?'auto':'');}"
"document.querySelector('#filters').open=filterNames.some(name=>params.get(name))||"
"(!!params.get('dateRole')&&params.get('dateRole')!=='auto')||(!!params.get('group')&&params.get('group')!=='paper');syncOrdering();}\n"
"function sortDescription(sort){sortHelp.textContent=sort==='relevance'?"
"(form.elements.namedItem('mode').value==='lexical'?"
"'Relevanz: seltene Begriffe und Treffer in Metadaten wiegen st\\u00e4rker. Textl\\u00e4nge und H\\u00e4ufigkeit flie\\u00dfen ein.':"
"(form.elements.namedItem('mode').value==='semantic'?"
"'Thematisch: Kosinus\\u00e4hnlichkeit von Titeln und Hauptformular-Abschnitten. Keine Wahrscheinlichkeiten.':"
"'Kombiniert: Kosinus\\u00e4hnlichkeit plus BM25/(1+BM25) aus der Wortsuche. Keine Wahrscheinlichkeiten.')):"
"'Die benannte Datumsrolle: Sitzungszeiten mit Zeitzone werden als Zeitpunkte sortiert. Unbekannte/ung\\u00fcltige Daten zuletzt. "
"Reine Tagesdaten haben keine behauptete Uhrzeit; ihre Sortiergrenze ist 00:00 UTC. Die gew\\u00e4hlte Rolle und Quelle stehen am Treffer.';}\n"
"function pagination(loading=false){for(const nav of navs){nav.hidden=!active||total===0;"
"if(!active)continue;const offset=Number(active.get('offset')||0),limit=Number(active.get('limit'));"
"nav.querySelector('[data-page]').textContent='Seite '+count.format(Math.floor(offset/limit)+1)+' von '+count.format(Math.ceil(total/limit));"
"nav.querySelector('[data-step=\"-1\"]').disabled=loading||offset===0;"
"nav.querySelector('[data-step=\"1\"]').disabled=loading||offset+limit>=total;}}\n",
"function renderHit(hit,rank){const article=element('article',undefined,'result-card');"
"const kinds={Paper:'Vorlage',Page:'PDF-Seite',File:'Datei',Meeting:'Sitzung',Person:'Person',Organization:'Organisation'};"
"const eyebrow=element('div',undefined,'eyebrow');eyebrow.append(element('span',String(rank)+'.'));"
"const reference=hit.relatedReference||hit.reference;if(reference)eyebrow.append(element('span',reference,'badge'));"
"if(hit.kind!=='Page')eyebrow.append(element('span',kinds[hit.kind]||hit.kind));article.append(eyebrow);"
"const paper=hit.kind==='Paper'?hit.id:hit.relatedPaper;"
"const heading=element('h2'),title=hitTitle(hit);"
"if(paper)localLink(heading,paperUrl(paper),title);else if(hit.kind==='Meeting')localLink(heading,'/meeting?'+new URLSearchParams({id:hit.id}),title);"
"else if(!original(heading,hit.documentUrl,title))localLink(heading,'/api/object?'+new URLSearchParams({id:hit.id,...(hit.page?{page:hit.page}:{})}),title);"
"article.append(heading);"
"const meta=element('div',undefined,'meta muted');"
"const sd=hit.sortDate,stamp=sd?(sd.precision==='invalid'?'Ung\\u00fcltiges Datum: '+sd.value:"
"date(sd.value)+(sd.precision==='instant'?' '+sd.value.slice(11):'')):"
"hit.dateRole==='document.date'?'Dokumentdatum nicht angegeben':'Datum unbekannt';"
"const dateLabel={'paper.date':'Vorlagendatum','meeting.start':'Sitzungsbeginn','meeting.end':'Sitzungsende',"
"'document.date':'Dokumentdatum',created:'Erstellungszeitstempel',modified:'\\u00c4nderungszeitstempel',"
"observedAt:'Archivstand',importedAt:'Indeximport',submittedAt:'Einreichung',decidedAt:'Entscheidung',"
"publishedAt:'Ver\\u00f6ffentlichung',effectiveAt:'Inkrafttreten'}[sd?.role||hit.dateRole]||'Datumsrolle';"
"const dateStamp=element('span',stamp);dateStamp.title=dateLabel;meta.append(dateStamp);"
"for(const value of [hit.relatedPaperType||hit.paperType,hit.relatedOrganization||hit.organization])"
"if(value)meta.append(element('span',value));article.append(meta);"
"const context=element('div',undefined,'meta muted'), meetings=new Map();"
"for(const edge of hit.evidence?.relationshipPath||[])if(edge.sourceKind==='Meeting')meetings.set(edge.source,edge.sourceDate);"
"const meetingDate=meetings.size===1&&hit.evidence?.relationshipsComplete!==false?[...meetings.values()][0]:null;"
"if(meetingDate)context.append(element('span','Sitzung: '+contextDate(meetingDate)));"
"for(const [property,label] of [['created','Dateieintrag erstellt'],['modified','Dateieintrag ge\\u00e4ndert']]){"
"const value=hit.evidence?.documentDates?.[property];if(value)context.append(element('span',label+': '+contextDate(value)));}",
"const resultContent=element('div',undefined,'result-content'),main=element('div',undefined,'result-main');"
"const excerpt=element('figure',undefined,'snippet');"
"excerpt.append(element('figcaption',hit.semanticText?'Thematischer PDF-Abschnitt \\u00b7 Seiten '+"
"hit.semantic.pageFirst+'\\u2013'+hit.semantic.pageLast:hit.page?'PDF-Text \\u00b7 Seite '+hit.page:'Metadatenauszug','snippet-label'));"
"const quote=element('blockquote'),text=hit.semanticText?Array.from(hit.semanticText):null;"
"quote.append(element('p',text?text.slice(0,420).join('')+(text.length>420?' ...':''):hit.snippet));excerpt.append(quote);main.append(excerpt);"
"if(hit.matchCount>1)main.append(element('p',count.format(hit.matchCount)+' passende Datens\\u00e4tze','muted'));"
"const actions=element('div',undefined,'actions');"
"originalPdf(actions,hit.documentUrl||hit.mainDocument?.documentUrl,hit.page||hit.mainDocument?'PDF \\u00f6ffnen':'Originaldokument \\u00f6ffnen',"
"hit.evidence?.citation?.documentVersion||hit.mainDocument?.documentVersion,hit.page);"
"if(paper)localLink(actions,paperUrl(paper),'Vorgang ansehen');main.append(actions);resultContent.append(main);"
"article.append(resultContent);",
"const notice=hit.preparation?.status==='failed'?' \\u00b7 Textextraktion fehlgeschlagen':"
"hit.warnings||hit.preparation?.status==='warnings'||['pdf-warnings','unsupported-layout','ambiguous'].includes(hit.preparation?.pageStatus)?' \\u00b7 Extraktionshinweise':'';"
"const details=element('details'), summary=element('summary','Details und Quellen'+notice);details.append(summary);"
"if(sd)details.append(element('p',dateLabel+': '+stamp+' ('+sd.role+')','muted'));"
"if(hit.semantic)details.append(element('p','Thematische Quelle: '+hit.semantic.source+'. Kosinus: '+"
"hit.semantic.cosine.toFixed(4)+' (keine Wahrscheinlichkeit).','muted'));"
"if(context.children.length)details.append(context);"
"if(hit.name&&(hit.page||hit.relatedName))details.append(element('p','Dokument: '+hit.name,'document'));"
"const facts=pdfFacts(hit.preparation);if(facts)details.append(facts);"
"const contextBlock=pdfContext(hit.preparation,title);if(contextBlock)details.append(contextBlock);"
"if(hit.matchCount>1)details.append(element('p','Die Anzahl passender Datens\\u00e4tze z\\u00e4hlt keine Wortvorkommen. Der Ausschnitt folgt der Sortierung.','muted'));"
"const provenance=element('p','Archivquelle: '+hit.source,'provenance muted');details.append(provenance);"
"const citation=hit.evidence?.citation;if(citation?.documentVersion){"
"localLink(details,'/api/object?'+new URLSearchParams({id:citation.documentVersion.id,...(hit.page?{page:hit.page}:{})}),'Zitierbare Fassung / Seite');"
"details.append(element('p','Quellenrolle: '+(hit.evidence.relationshipPath.map(r=>r.role).join(', ')||'eigenst\\u00e4ndiges Objekt')+"
"'. SHA-256: '+citation.documentVersion.sha256+'. Original-URLs k\\u00f6nnen sp\\u00e4ter andere Bytes liefern.','provenance muted'));}"
"if(sd)details.append(element('p','Datumsquelle: '+sd.sourceObject+' / '+sd.property+' / '+sd.rule,'provenance muted'));"
"original(details,hit.id,'OParl-Metadaten');"
"if(hit.evidence?.relationshipsComplete===false){const r=hit.evidence.relationsAvailable;"
"details.append(element('p',hit.evidence.relationshipTotal+' Quellenbeziehungen; nur ein Ausschnitt wird angezeigt.','muted'));"
"localLink(details,'/api/object?'+new URLSearchParams({id:r.id,view:r.view,direction:r.direction,snapshotId:r.snapshotId}),"
"'Quellenbeziehungen paginiert nachladen');}"
"if(hit.warnings)details.append(element('p','Extraktionswarnungen: '+hit.warnings+' (siehe Indexstatus)','warning'));"
"const content=element('div');details.append(content);let loaded=false,pending=false;"
"details.addEventListener('toggle',async()=>{if(!details.open||loaded||pending)return;pending=true;"
"content.replaceChildren(element('p','Wird geladen ...'));try{const params=hit.preparation?.available||{id:hit.id,raw:'true',...(hit.page?{page:hit.page}:{})};"
"await loadPdfPage(content,params);"
"loaded=true;}catch(error){content.replaceChildren(element('p','Fehler: '+error.message,'warning'));}finally{pending=false;}});"
"article.append(details);return article;}\n",
"async function search(params){if(controller)controller.abort();controller=new AbortController();const current=++sequence;"
"if(!params.has('limit'))params.set('limit','50');if(!params.has('sort'))params.set('sort','relevance');"
"if(!params.has('group'))params.set('group','paper');"
"results.replaceChildren();results.setAttribute('aria-busy','true');status.dataset.error='false';status.textContent='Suche l\\u00e4uft ...';"
"pagination(true);sortDescription(params.get('sort'));"
"try{const data=await api('/api/search?'+params,controller.signal);if(current!==sequence)return;"
"const offset=Number(params.get('offset')||0),limit=Number(params.get('limit'));"
"if(data.total&&offset>=data.total){params.set('offset',String(Math.floor((data.total-1)/limit)*limit));"
"history.replaceState(null,'','/?'+params);return search(params);}"
"active=new URLSearchParams(params);active.set('snapshotId',data.snapshotId);total=data.total;"
"const unit=data.countUnit==='document-version'?'Dokumentfassungen':data.countUnit==='record'?'Datens\\u00e4tze':'Vorg\\u00e4nge/eigenst\\u00e4ndige Objekte';"
"status.textContent=data.hits.length?count.format(offset+1)+'\\u2013'+count.format(offset+data.hits.length)+' von '+count.format(total)+' Treffern':"
"count.format(total)+' Treffer'+(total?' \\u2013 keine auf dieser Seite.':'.');"
"status.textContent+=' Z\\u00e4hleinheit: '+unit+'.';"
"if(data.excludedUnknownDateRecords||data.excludedInvalidDateRecords)status.textContent+=' Ausgeschlossen: '+"
"count.format(data.excludedUnknownDateRecords)+' Datens\\u00e4tze mit unbekanntem und '+count.format(data.excludedInvalidDateRecords)+' mit ung\\u00fcltigem Datum.';",
"if(data.excludedUnversionedRecords)status.textContent+=' '+count.format(data.excludedUnversionedRecords)+' Datens\\u00e4tze ohne archivierte Dokumentfassung ausgeschlossen.';"
"for(const [i,hit] of data.hits.entries())results.append(renderHit(hit,offset+i+1));"
"if(!data.total)results.append(element('p','Keine Treffer. Versuche andere Suchbegriffe oder weniger Filter.','panel empty'));"
"}catch(error){if(current!==sequence||error.name==='AbortError')return;active=null;total=0;"
"status.dataset.error='true';status.textContent='Fehler: '+error.message;"
"}finally{if(current===sequence){results.setAttribute('aria-busy','false');pagination();}}}\n"
"function navigate(params,scroll=false){history.pushState(null,'','/?'+params);restore(params);"
"search(params);if(scroll)status.scrollIntoView({block:'start'});}\n"
"form.addEventListener('submit',event=>{event.preventDefault();const params=new URLSearchParams(new FormData(form));"
"for(const [name,value] of [...params])if(!value)params.delete(name);navigate(params);});"
"ordering.addEventListener('change',()=>{if(ordering.value==='chronological')form.elements.namedItem('sort').value=chronologicalSort;"
"else{form.elements.namedItem('mode').value=ordering.value;form.elements.namedItem('sort').value='relevance';}"
"syncOrdering();form.requestSubmit();});"
"direction.addEventListener('click',()=>{const sort=form.elements.namedItem('sort');sort.value=sort.value==='date-desc'?'date-asc':'date-desc';"
"syncOrdering();form.requestSubmit();});"
"for(const name of ['limit','group'])form.elements.namedItem(name).addEventListener('change',()=>form.requestSubmit());"
"for(const nav of navs)for(const button of nav.querySelectorAll('[data-step]'))button.addEventListener('click',()=>{"
"if(!active)return;const params=new URLSearchParams(active),limit=Number(params.get('limit'));"
"params.set('offset',String(Math.max(0,Number(params.get('offset')||0)+Number(button.dataset.step)*limit)));navigate(params,true);});\n"
"addEventListener('popstate',()=>{const params=new URLSearchParams(location.search);restore(params);"
"if(hasCriteria(params))search(params);else{if(controller)controller.abort();sequence++;active=null;total=0;pagination();"
"results.replaceChildren();results.setAttribute('aria-busy','false');status.dataset.error='false';"
"status.textContent='Suchanfrage eingeben.';sortDescription(params.get('sort')||'relevance');}});\n"
"const initial=new URLSearchParams(location.search);restore(initial);sortDescription(initial.get('sort')||'relevance');"
"api('/api/semantic-status').then(data=>{for(const option of ordering.options)"
"if(option.value==='semantic'||option.value==='hybrid')option.disabled=!data.enabled;"
"if(data.enabled){const help=document.querySelector('#semantic-help');help.hidden=false;help.textContent="
"'Thematisch/Kombiniert: '+count.format(data.titles)+' Titel, '+count.format(data.passages)+' Hauptformular-Abschnitte. '"
"+count.format(data.excludedMainForms)+' Hauptformulare ausgeschlossen; Anlagen nicht erfasst.';}"
"}).catch(error=>{const help=document.querySelector('#semantic-help');help.hidden=false;help.textContent='Fehler: '+error.message;"
"document.querySelector('#search-help').open=true;});"
"const catalogs=[{kind:'Organization',list:'organization-ids'},{kind:'Person',list:'actor-ids'}],idsMore=document.querySelector('#ids-more');"
"async function loadIds(first=false){idsMore.disabled=true;try{await Promise.all(catalogs.filter(c=>first||c.next).map(async c=>{"
"const data=await api('/api/options?'+new URLSearchParams({kind:c.kind,fields:'name',...(c.next?{offset:c.next.offset,snapshotId:c.next.snapshotId}:{})}));"
"c.next=data.next;for(const object of data.objects){const option=element('option');option.value=object.id;option.label=object.metadata?.name||object.id;"
"document.querySelector('#'+c.list).append(option);}}));idsMore.hidden=!catalogs.some(c=>c.next);}"
"catch(error){status.textContent='ID-Auswahl nicht verf\\u00fcgbar: '+error.message;status.dataset.error='true';}finally{idsMore.disabled=false;}}"
"idsMore.addEventListener('click',()=>loadIds());loadIds(true);"
"if(hasCriteria(initial))search(initial);}\n",
"async function showCase(){const status=document.querySelector('#case-status'),id=new URLSearchParams(location.search).get('id');"
"const meeting=location.pathname==='/meeting',endpoint=meeting?'/api/meeting':'/api/paper',objects=new Map();"
"let snapshot,nextPage,agendaNext;const more=document.querySelector('#case-more'),agendaMore=document.querySelector('#agenda-more');"
"function failure(error){status.textContent='Fehler: '+error.message;status.className='warning';}"
"function details(parent,node){const detail=element('details');detail.append(element('summary','Rohmetadaten explizit laden'));let loaded=false;"
"detail.addEventListener('toggle',async()=>{if(!detail.open||loaded||!node.indexed)return;loaded=true;try{"
"const raw=await api('/api/object?'+new URLSearchParams({id:node.id,raw:'true',snapshotId:snapshot}));"
"detail.append(element('pre',JSON.stringify(raw.metadata,null,2)));}catch(error){loaded=false;detail.append(element('p',error.message,'warning'));}});parent.append(detail);}"
"function renderDocument(parent,node,label){const m=node.metadata||{},item=element('div',undefined,'panel');"
"item.append(element('h4',label+': '+(m.name||m.fileName||node.id)));originalPdf(item,documentUrl(m),'Original-PDF \\u00f6ffnen',node.citation?.documentVersion,1);"
"const version=node.citation?.documentVersion||node.documentVersion;if(version){localLink(item,'/api/object?'+"
"new URLSearchParams({id:version.id}),'Zitierbare Dokumentfassung');item.append(element('p','SHA-256: '+version.sha256,'provenance muted'));}"
"if(!node.indexed)item.append(element('p','Nicht als eigener Datensatz im Snapshot verf\\u00fcgbar.','warning'));"
"if(node.documentCoverage==='not-archived-at-index-build')item.append(element('p','Beim Indexaufbau nicht lokal archiviert. Die Ursache ist nicht belegt.','warning'));"
"else if(node.documentCoverage==='missing-version-cause-unknown')item.append(element('p','Keine lokale Dokumentfassung; Ursache unbekannt.','warning'));"
"else if(node.documentCoverage==='binary-present-extraction-failed')item.append(element('p','Dokument archiviert, Textextraktion fehlgeschlagen.','warning'));"
"else if(node.warnings)item.append(element('p','Lokale Extraktionswarnungen: '+node.warnings,'warning'));"
"const facts=pdfFacts(node.preparation);if(facts)item.append(facts);"
"if(node.preparation?.available){const pdf=element('details'),content=element('div');let loaded=false,pending=false;"
"pdf.append(element('summary','PDF-Befunde und Seitentext'),content);"
"pdf.addEventListener('toggle',async()=>{if(!pdf.open||loaded||pending)return;pending=true;content.replaceChildren(element('p','Wird geladen ...'));"
"try{await loadPdfPage(content,node.preparation.available);loaded=true;}catch(error){content.replaceChildren(element('p','Fehler: '+error.message,'warning'));}finally{pending=false;}});item.append(pdf);}"
"details(item,node);parent.append(item);}\n",
"function render(data){const root=objects.get(id)||[...objects.values()].find(o=>o.sourceRole==='root'),m=root?.metadata||{};"
"document.querySelector('#case-reference').textContent=m.reference||(meeting?'Sitzung':'');"
"document.querySelector('#case-title').textContent=m.name||id;document.title=(m.reference||m.name||'Recherche')+' | OParl-Suche';"
"document.querySelector('#case-meta').textContent=[m.start||m.date,m.paperType,root?.lifecycle].filter(Boolean).join(' | ');"
"if(data.overview){const overview=document.querySelector('#case-overview');overview.hidden=false;"
"overview.textContent=data.overview.directDocuments+' direkte Dokumente; '+data.overview.consultations+' Beratungen; '+"
"data.overview.relatedPapers+' verkn\\u00fcpfte Vorg\\u00e4nge. Neueste belegte Sitzung zuerst; unbekannte Zeiten zuletzt.';}"
"const conflict=document.querySelector('#case-conflict');conflict.hidden=!root?.statusConflict;"
"conflict.textContent=root?.statusConflict?'Quellenwiderspruch: als geplant oder abgesagt gemeldet, aber '+"
"root.agendaItemsWithResult+' TOP mit Ergebnis. Der Quellstatus bleibt unver\\u00e4ndert.':'';"
"document.querySelector('#case-description').textContent=m.description||(root?.omittedFields?.includes('description')?'Beschreibung in den Rohmetadaten verf\\u00fcgbar.':'');"
"for(const name of ['case-actions','case-files','case-relations','case-consultations'])document.querySelector('#'+name).replaceChildren();"
"for(const detail of document.querySelectorAll('#case-summary>details'))detail.remove();"
"const actions=document.querySelector('#case-actions');localLink(actions,endpoint+'?'+new URLSearchParams({id}),'Kompakte Daten als JSON');"
"original(actions,m.web,'Original im RIS');details(document.querySelector('#case-summary'),root);"
"if(meeting){document.querySelector('#meeting-agenda-section').hidden=false;"
"document.querySelector('#documents-title').textContent='Sitzungsdokumente';}"
"const files=document.querySelector('#case-files'),relations=document.querySelector('#case-relations'),timeline=document.querySelector('#case-consultations');"
"for(const node of objects.values()){if(node.kind==='File'&&(meeting||node.scope==='directSource'))renderDocument(files,node,node.sourceRole);"
"if(node.scope==='relatedPaper'){const p=element('p');if(node.indexed)localLink(p,paperUrl(node.id),node.metadata?.name||node.id);"
"else p.textContent=node.id+' (nicht indexiert)';relations.append(p);}"
"if(node.kind==='Consultation'){const article=element('article'),c=node.consultation||{};"
"article.append(element('h3',node.metadata?.role||'Beratung'),element('p',c.authority==='authoritative'?"
"'Entscheidungsberatung laut authoritative; ein Ergebnis braucht einen eigenen TOP-Beleg':c.authority==='preliminary'?'Vorberatung / vorl\\u00e4ufig laut Quelle':'Ergebnisverbindlichkeit unbekannt'));"
"for(const context of c.context||[]){const object=context.object,a=object.metadata||{};"
"const p=element('p',[context.role,a.name,a.start,a.result,object.lifecycle].filter(Boolean).join(' | '));article.append(p);"
"if(object.statusConflict)article.append(element('p','Quellenwiderspruch: Sitzungsstatus und dokumentierte TOP-Ergebnisse passen nicht zusammen.','warning'));"
"if(context.role==='consultation.meeting')localLink(article,'/meeting?'+new URLSearchParams({id:object.id}),'Sitzung und Tagesordnung');}"
"for(const source of c.decisionSources||[])renderDocument(article,objects.get(source.id)||{...source,citation:{documentVersion:source.documentVersion}},'Beschlussquelle');"
"if(c.moreContextAvailable||c.moreDecisionSourcesAvailable)article.append(element('p','Weitere Beziehungsbelege in den explizit nachladbaren Rohdaten.','muted'));"
"details(article,node);timeline.append(article);}}\n",
"const gaps=data.localCoverage.unindexedObjects;"
"status.textContent=count.format(objects.size)+' von '+count.format(data.total)+' verkn\\u00fcpften Objekten geladen; Snapshot '+snapshot+'. '+"
"(gaps?count.format(gaps)+' lokale Beziehungsziele fehlen. ':'')+(data.incomplete?'Globale Archivl\\u00fccken sind bekannt.':'');"
"status.className='muted';document.querySelector('#case-content').hidden=false;more.hidden=!nextPage;}\n"
"async function load(args={}){more.disabled=true;try{const data=await api(endpoint+'?'+new URLSearchParams({id,...args}));"
"snapshot=data.snapshotId;nextPage=data.next;for(const node of data.objects)objects.set(node.id,node);render(data);"
"}catch(error){failure(error);}finally{more.disabled=false;}}"
"more.addEventListener('click',()=>{if(nextPage)load({offset:nextPage.offset,snapshotId:nextPage.snapshotId,limit:nextPage.limit});});"
"agendaMore.addEventListener('click',async()=>{agendaMore.disabled=true;try{const args=agendaNext?"
"{offset:agendaNext.offset,snapshotId:agendaNext.snapshotId,limit:agendaNext.limit}:{snapshotId:snapshot};"
"const data=await api('/api/agenda?'+new URLSearchParams({id,...args}));agendaNext=data.next;"
"document.querySelector('#agenda-status').textContent=data.total+' TOP-Referenzen; '+data.unresolvedAgendaReferences+"
"' nicht aufgel\\u00f6st; '+data.nonPublicReferences+' ausdr\\u00fccklich nicht\\u00f6ffentlich. Tagesordnungsstatus: '+data.meeting.agendaStatus+"
"(data.meeting.statusConflict?' (Quellenwiderspruch: Ergebnisse trotz geplantem/abgesagtem Status)':'');"
"for(const node of data.objects){const m=node.metadata||{},article=element('article');"
"article.append(element('h3',['TOP '+(m.number||'?'),m.name].filter(Boolean).join(' | ')));"
"if(m.result)article.append(element('p','Ergebnis: '+m.result));"
"if(!node.indexed)article.append(element('p','TOP-Referenz '+node.id+' ist nicht im lokalen Index aufgel\\u00f6st.','warning'));"
"details(article,node);document.querySelector('#meeting-agenda').append(article);}"
"agendaMore.textContent=agendaNext?'Weitere TOP laden':'Tagesordnung vollst\\u00e4ndig geladen';agendaMore.hidden=!agendaNext;"
"}catch(error){failure(error);}finally{agendaMore.disabled=false;}});await load();}\n"
"if(document.querySelector('#health-status'))health();else if(document.querySelector('#case-status'))showCase();else initSearch();\n", 0};

